import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
ribbons = data[1:]

max_beauty = max(ribbons.count(ribbon) for ribbon in ribbons)
winners = [index for index, ribbon in enumerate(ribbons) if ribbons.count(ribbon) == max_beauty]

if len(winners) == 1:
    if winners[0] == 0:
        print("Kuro")
    elif winners[0] == 1:
        print("Shiro")
    else:
        print("Katie")
else:
    print("Draw")
